<style>
.apb-outer{
  position:relative;
  left:50%;right:50%;
  margin-left:-50vw;margin-right:-50vw;
  width:100vw;
  overflow:hidden;
}
.apb{
  background:#f5a623;
  width:100%;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:9px 16px;
  font-family:var(--font-body-family,'DM Sans',sans-serif);
  font-size:13px;
  color:#fff;
  white-space:nowrap;
  border-bottom:1px solid rgba(0,0,0,.1);
  overflow:hidden;
}

/* Contenu statique desktop */
.apb-static{
  display:flex;
  align-items:center;
  gap:6px;
  white-space:nowrap;
}

/* Marquee mobile */
.apb-marquee-wrap{
  display:none;
  overflow:hidden;
  width:100%;
}
.apb-marquee-track{
  display:inline-flex;
  align-items:center;
  gap:0;
  white-space:nowrap;
  animation:apbScroll 18s linear infinite;
}
.apb-marquee-track:hover{animation-play-state:paused;}
.apb-marquee-item{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding-right:48px;
}
@keyframes apbScroll{
  0%{transform:translateX(0);}
  100%{transform:translateX(-50%);}
}

.apb-bold{font-weight:700;}
.apb-sep{opacity:.45;margin:0 4px;}
.apb-code{
  background:rgba(0,0,0,.18);
  border-radius:3px;
  padding:1px 8px;
  font-weight:700;
  letter-spacing:.05em;
}
.apb-timer{
  display:inline-flex;
  align-items:baseline;
  gap:3px;
  font-weight:700;
  font-variant-numeric:tabular-nums;
}
.apb-unit{font-size:10px;font-weight:600;opacity:.7;}

/* Sur mobile : masquer statique, afficher marquee */
@media(max-width:700px){
  .apb-static{display:none;}
  .apb-marquee-wrap{display:block;}
  .apb{padding:9px 0;justify-content:flex-start;}
}
</style>

<div class="apb-outer">
  <div class="apb" role="banner">

    <!-- Desktop : 1 ligne fixe -->
    <div class="apb-static">
      <span>🔥</span>
      <span><span class="apb-bold">{{ txt_main }}</span> {{ txt_with }}</span>
