    margin: 0 0 10px;
  }
  .apx-how__sub{
    color: #9a9690;
    font-size: 15px;
    font-weight: 300;
    margin: 0;
  }

  /* ── GRID desktop ── */
  .apx-how__track{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }

  /* ── CARTE ── */
  .apx-step{
    text-align: center;
    padding: 28px 18px 24px;
    background: #141416;
    border: 1px solid rgba(255,255,255,.07);
    border-radius: 16px;
    transition: border-color .25s, transform .25s;
  }
  .apx-step:hover{
    border-color: rgba(245,166,35,.25);
    transform: translateY(-5px);
  }

  /* ── ICÔNE ── */
  .apx-step__icon{
    width: 80px;
    height: 80px;
    border-radius: 999px;
    margin: 0 auto 16px;
    display: grid;
    place-items: center;
    position: relative;
  }
  .apx-step__icon::after{
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: 999px;
    background: radial-gradient(circle at 30% 20%, rgba(255,255,255,.15), transparent 55%);
    pointer-events: none;
  }
  .apx-step__icon--1{ background: rgba(245,166,35,.12); border: 1px solid rgba(245,166,35,.2); color: #f5a623; }
