    margin: 0;
  }

  /* ── DOTS (cachés desktop) ── */
  .apx-dots{ display: none; }

  /* ── CTA ── */
  .apx-how__cta{ text-align: center; margin-top: 40px; }
  .apx-how__btn{
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 15px 36px;
    border-radius: 99px;
    background: #f5a623;
    color: #000;
    font-family: 'Bebas Neue', sans-serif;
    font-size: 18px;
    letter-spacing: .06em;
    text-decoration: none;
    transition: background .2s, transform .2s, box-shadow .2s;
    box-shadow: 0 8px 24px rgba(245,166,35,.25);
  }
  .apx-how__btn:hover{
    background: #fff;
    transform: translateY(-2px);
    box-shadow: 0 12px 32px rgba(255,255,255,.15);
  }
  .apx-how__btn:active{ transform: translateY(0); opacity: .92; }

  .apx-how__trust{
    margin-top: 14px;
    color: #9a9690;
    font-size: 13px;
    font-weight: 300;
  }
  .apx-trust-dot{
    display: inline-block;
    width: 4px; height: 4px;
    border-radius: 999px;
    background: rgba(245,166,35,.5);
    margin: 0 10px;
    transform: translateY(-2px);
  }

  /* ── REVEAL ── */
  .apx-reveal{ opacity: 0; transform: translateY(16px); transition: opacity .6s ease, transform .6s ease; }
  .apx-reveal.is-visible{ opacity: 1; transform: translateY(0); }

  /* ══ MOBILE carousel ══ */
  @media(max-width: 760px){
    .apx-how{ padding: 52px 0; }
    .apx-how__inner{ padding: 0; }
    .apx-how__head{ padding: 0 20px; }

    .apx-how__track{
      display: flex;
      overflow-x: scroll;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      gap: 0;
      padding: 4px 0 16px;
    }
    .apx-how__track::-webkit-scrollbar{ display: none; }

    .apx-step{
      flex: 0 0 calc(100vw - 64px);
      max-width: 300px;
      scroll-snap-align: center;
      margin: 0 10px;
      transform: none !important;
    }
    .apx-step:first-child{ margin-left: calc((100vw - (100vw - 64px)) / 2); }
    .apx-step:last-child { margin-right: calc((100vw - (100vw - 64px)) / 2); }
    .apx-step.is-active{ border-color: rgba(245,166,35,.3); background: rgba(245,166,35,.04); }

    .apx-dots{
      display: flex;
      justify-content: center;
      gap: 8px;
      margin: 4px 0 20px;
    }
    .apx-dot-btn{
      width: 8px; height: 8px;
      border-radius: 99px;
      border: none;
      background: rgba(255,255,255,.2);
      padding: 0; cursor: pointer;
      transition: background .2s, width .2s;
