      background: transparent;
      color: #f5a623;
      border: 1px solid rgba(245,166,35,.4);
      box-shadow: none;
    }
    .apx-how__btn:hover{
      background: rgba(245,166,35,.08);
      color: #f5a623;
      box-shadow: none;
    }
  }

  @media(prefers-reduced-motion: reduce){
    .apx-step, .apx-how__btn, .apx-reveal{ transition: none !important; }
  }
</style>

<script>
(function(){
  var section = document.getElementById('apx-how');
  if(!section || section.dataset.apxInit === '1') return;
  section.dataset.apxInit = '1';

  /* Reveal */
  var revealEls = section.querySelectorAll('.apx-reveal');
  if(revealEls.length){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('is-visible'); io.unobserve(e.target); }
      });
    },{ threshold: 0.15 });
    revealEls.forEach(function(el, i){ el.style.transitionDelay = (i * 70) + 'ms'; io.observe(el); });
  }

  /* Carousel dots */
  var track = document.getElementById('apx-track');
  var dots  = document.querySelectorAll('#apx-dots .apx-dot-btn');
  var cards = track ? track.querySelectorAll('.apx-step') : [];
  if(!track || !dots.length || !cards.length) return;

  function onScroll(){
    var idx = Math.round(track.scrollLeft / (track.scrollWidth / cards.length));
    idx = Math.max(0, Math.min(idx, cards.length - 1));
    dots.forEach(function(d, i){ d.classList.toggle('active', i === idx); });
    cards.forEach(function(c, i){ c.classList.toggle('is-active', i === idx); });
  }

  dots.forEach(function(dot){
    dot.addEventListener('click', function(){
      var card = cards[parseInt(this.dataset.idx, 10)];
      if(card) track.scrollTo({ left: card.offsetLeft - (track.offsetWidth - card.offsetWidth) / 2, behavior: 'smooth' });
    });
  });

  track.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();
</script>

