<section class="apx-reco" id="apx-reco">
  <div class="apx-reco__inner">
    <div class="apx-reco__head">
      <span class="apx-reco__badge">{{ t_badge }}</span>
      <h2 class="apx-reco__title">{{ t_title }}</h2>
      <p class="apx-reco__sub">{{ t_sub }}</p>
    </div>
    <div class="apx-reco__track" id="apx-reco-track">
      {%- assign shown = 0 -%}
      {%- for p in reco_col.products -%}
        {%- if p.id == product.id or p.available == false -%}{%- continue -%}{%- endif -%}
        {%- assign shown = shown | plus: 1 -%}
        {%- comment -%} Nom court : « Portrait Naruto personnalisé | À partir de ta photo » -> « Portrait Naruto personnalisé » {%- endcomment -%}
        {%- assign p_name = p.title | split: ' — ' | first -%}
        {%- assign p_head = p_name | split: ' | ' | first -%}
        {%- unless p_head == 'Portrait personnalisé' or p_head == 'Portrait manga personnalisé' or p_head == 'Portrait Cartoon personnalisé' -%}
          {%- assign p_name = p_head -%}
        {%- endunless -%}
        <a class="apx-reco__card" href="{{ p.url }}">
          <div class="apx-reco__img-wrap">
            {%- if p.featured_image -%}
              <img src="{{ p.featured_image | image_url: width: 400 }}" alt="{{ p.featured_image.alt | default: p_name | escape }}" width="400" loading="lazy">
            {%- endif -%}
          </div>
          <div class="apx-reco__info">
            <p class="apx-reco__name">{{ p_name }}</p>
            <p class="apx-reco__price">{{ t_from }} {{ p.price_min | money }}</p>
          </div>
          <span class="apx-reco__btn">{{ t_go }}</span>
        </a>
        {%- if shown >= 4 -%}{%- break -%}{%- endif -%}
      {%- endfor -%}
    </div>
    {%- if shown > 1 -%}
    <div class="apx-reco__dots" id="apx-reco-dots" aria-hidden="true">
      {%- for i in (1..shown) -%}<button class="apx-reco__dot{% if forloop.first %} active{% endif %}" data-idx="{{ forloop.index0 }}"></button>{%- endfor -%}
    </div>
    {%- endif -%}
    <div class="apx-reco__footer">
      <a href="{{ reco_col.url }}" class="apx-reco__collection-btn">{{ t_collection }}</a>
    </div>
  </div>
</section>

