  }
  .apx-reco__card:hover .apx-reco__btn{
    background: #f5a623; color: #000; border-color: #f5a623;
  }
  .apx-reco__footer{ text-align: center; margin-top: 28px; }
  .apx-reco__collection-btn{
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 20px;
    border-radius: 99px;
    border: 1px solid rgba(245,166,35,.35);
    background: transparent;
    color: #f5a623;
    font-family: 'Bebas Neue', sans-serif;
    font-size: 13px;
    letter-spacing: .06em;
    text-decoration: none;
    transition: background .2s, border-color .2s, color .2s;
  }
  .apx-reco__collection-btn:hover{
    background: #f5a623; border-color: #f5a623; color: #000;
  }
  .apx-reco__dots{ display: none; }

  @media(max-width: 760px){
    .apx-reco{ padding: 52px 0; }
    .apx-reco__inner{ padding: 0; }
    .apx-reco__head{ padding: 0 20px; }
    .apx-reco__track{
      overflow-x: scroll;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      gap: 0;
      padding: 4px 0 12px;
    }
    .apx-reco__track::-webkit-scrollbar{ display: none; }
    .apx-reco__card{
      flex: 0 0 calc(100vw - 80px);
      max-width: 260px;
      scroll-snap-align: center;
      margin: 0 8px;
      transform: none !important;
    }
    .apx-reco__card:first-child{ margin-left: calc((100vw - (100vw - 80px)) / 2); }
    .apx-reco__card:last-child{ margin-right: calc((100vw - (100vw - 80px)) / 2); }
    .apx-reco__dots{
      display: flex; justify-content: center; gap: 8px; margin: 8px 0 0;
    }
    .apx-reco__dot{
      width: 8px; height: 8px; border-radius: 99px; border: none;
      background: rgba(255,255,255,.2); padding: 0; cursor: pointer;
      transition: background .2s, width .2s;
    }
    .apx-reco__dot.active{ background: #f5a623; width: 22px; }
    .apx-reco__collection-btn{ font-size: 12px; padding: 8px 18px; width: auto; }
  }

  @media(min-width: 761px) and (max-width: 1024px){
    .apx-reco__card:nth-child(4){ display: none; }
  }

  @media(prefers-reduced-motion: reduce){
    .apx-reco__card,
    .apx-reco__img-wrap img{ transition: none !important; }
  }
</style>

<script>
(function(){
  var section = document.getElementById('apx-reco');
  if(!section || section.dataset.apxInit === '1') return;
  section.dataset.apxInit = '1';

  var track = document.getElementById('apx-reco-track');
  var dots  = document.querySelectorAll('#apx-reco-dots .apx-reco__dot');
  var cards = track ? track.querySelectorAll('.apx-reco__card') : [];
  if(!track || !dots.length || !cards.length) return;

  function onScroll(){
    var idx = Math.round(track.scrollLeft / (track.scrollWidth / cards.length));
    idx = Math.max(0, Math.min(idx, cards.length - 1));
    dots.forEach(function(d,i){ d.classList.toggle('active', i === idx); });
    cards.forEach(function(c,i){ c.classList.toggle('is-active', i === idx); });
  }

  dots.forEach(function(dot){
    dot.addEventListener('click', function(){
      var card = cards[parseInt(this.dataset.idx, 10)];
      if(card) track.scrollTo({
        left: card.offsetLeft - (track.offsetWidth - card.offsetWidth) / 2,
        behavior: 'smooth'
      });
    });
  });

  track.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();
</script>
